import { Background } from '../backgrounds';

export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "約半年後。白天。朝倉家。江東區。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "廚房的窗戶開了一半。十月的光進來。不是——凌晨的灰。是——上午的黃。落在流理台上。落在牛奶盒上。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）牛奶過期了。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她拿著牛奶盒。背面印著日期。昨天。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）過期了。昨天就過期了。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）上一輪——不是這樣。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手停了一下。然後——把牛奶盒放進垃圾桶。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）沒有上一輪了。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）沒有上一輪了。這是——這一輪的牛奶。這一輪——過期了。這一輪——我昨天忘記看。就這樣。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "客廳。悠真坐在矮桌前面。桌上有一本筆記本。不是——實驗記錄。不是——研究資料。是一本普通的方格筆記本。封面被他自己貼了一張貼紙。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "筆記本翻開。四欄。他自己畫的線。字跡歪歪的。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "我的記憶。不知道是誰的。已經不會發生的。還不能確認的。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）悠真的筆記。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）四欄。他自己分的。我的記憶——是他自己的。不知道是誰的——是那些不像他的、不屬於他的碎片。已經不會發生的——是被避免的、不會再來的版本。還不能確認的——是他不確定是不是真的、還沒有發生也無法驗證的。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）fragments——不再更新了。從那一天之後——沒有新的。他保留的是——之前接收到的。靜態的。不再持續。不再被用來選擇公共政策。不再被用來做任何事。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）筆記由他自己保管。不自動上傳。不連任何系統。醫療和家屬——只在他同意的時候看。不是——研究採樣。是——他自己的東西。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "悠真在「還不能確認的」那一欄寫了一行字。停下來。看了很久。然後——把筆放下。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraYuma, character: "朝倉悠真", dialogue: "姐。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraYuma_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "嗯？", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraYuma, character: "朝倉悠真", dialogue: "如果我還記得一件以後會發生的事呢？", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraYuma_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他沒有抬頭。他的手指壓著筆記本的那一行字。聲音很輕。像在問一個他想了很久的問題。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他在問。如果——他還記得一件以後會發生的事。一件——還沒來的。一件——可能會來的。他問我——怎麼辦。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）以前的我會說什麼？以前的我會說——那我們一定要阻止。以前的我會說——告訴我內容。以前的我會說——我們提前改掉它。以前的——整個循環就是這樣運作的。知道未來。改掉未來。消耗未來。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——未來不是證物。至少——現在不是。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在他對面坐下。矮桌中間隔著筆記本。她沒有伸手去翻。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "等它真的來了，再一起看。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraYuma, character: "朝倉悠真", dialogue: "⋯⋯", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraYuma_Base },
    { characterId: CharacterId.AsakuraYuma, character: "朝倉悠真", dialogue: "不是——一定要阻止？", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraYuma_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "不一定。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "未來不是證物。至少現在不是。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "悠真看著她。幾秒。然後——點了一下頭。很小的。像在確認什麼。不是——被說服了。是——收到了。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他沒有立即回到學校。先——復健。心理。睡眠醫療。還有夜驚。還有混淆。有時候——失眠。不是——「獲救」了就什麼都好了。不是——從研究中心出來就變回原來的悠真。創傷——不會因為壞人被審判就消失。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "窗外。電車的聲音。遠遠的。不是——那一天的。是——今天的。普通的。延誤了。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "手機螢幕亮了一下。電車延遲通知。十分鐘。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）電車延誤。十分鐘。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）上一輪——不是這樣。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）沒有上一輪了。", background: Background.Chapter_28_Ch28_Act7_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把手機翻過去。螢幕朝下。", background: Background.Chapter_28_Ch28_Act7_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "下午。客廳。矮櫃上面。小鏡子。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "它經證物程序依法返還了。不是——被沒收。不是——被銷毀。是——走完了證物流程。法院簽了返還文件。它回到了朝倉家。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）小鏡子。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）悠真在它背面刻過受試者編號。它被用來——確認身分。被用來——追蹤。被用來——把一個十五歲的孩子變成研究樣本。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——鏡子本身沒有做過任何事。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "悠真走過來。看著矮櫃上的鏡子。他伸手拿起來。翻到背面。他自己刻的那一串數字。他的手指摸過去。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraYuma, character: "朝倉悠真", dialogue: "要砸掉嗎？", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraYuma_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "不用。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "物件沒有罪。制度曾如何使用它，才需要被記住。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "悠真看了她一下。然後——把鏡子放進抽屜。不是——砸碎。不是——擺在顯眼的地方。是——放進抽屜。可以留著。可以——不每天看見。可以——在需要的時候打開。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他放進去了。抽屜。不是——儀式。不是——銷毀。只是——放好。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "傍晚。澪一個人在客廳。悠真在房間裡。門關著。有時候——裡面會傳出翻筆記本的聲音。有時候——安靜。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手機在桌上。螢幕暗著。聯絡人列表裡——白石琴音。還在。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）琴音。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）我沒有刪掉。也沒有——主動聯絡。號碼還在。名字還在。最後一則訊息——停在三個月前。沒有新的。沒有——從她那邊來的。也沒有——從我這邊去的。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）關係——沒有恢復。也沒有——被我永久判死。只是——在那裡。像——一個還沒有被翻到的頁面。不是——必須現在翻。也不是——必須永遠不翻。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把手機拿起來。看了一下聯絡人。然後——放回桌上。螢幕暗下去。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）我也有自己的記錄。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的背包裡。一本筆記本。比悠真的小。封面沒有貼紙。裡面——三欄。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "我記得。本輪可證。不能成為證據。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）我記得——前輪千田死亡。本輪可證——千田活著。不能成為證據——前輪的刺傷地點、前輪的琴音、R4、被避免的未來。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）這些——不進 Public Witness Index。不被法院視為既定事實。可是——也沒有人要求我刪除。沒有人——要求我說服自己「沒有發生」。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）我記得。它發生過。在我記得的那一輪裡——它發生過。法律不能拿它定罪。法院不能拿它當事實。可是——我不需要假裝它不存在。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把筆記本放回背包。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "窗外的光繼續暗。電車的聲音又過了一班。不延誤了。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）06:13。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她下意識看了一眼牆上的時鐘。不是——06:13。是——17:48。傍晚。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不是 06:13。是傍晚。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是——早上。早上我醒來的時候。05:50。我——醒了。在 06:13 之前。我盯著時鐘。05:51。05:55。06:00。06:05。06:10。06:12。06:12:30。06:12:45。06:12:50。06:12:55。06:12:58。06:12:59。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）06:13:00。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）我盯著它越過去了。然後——06:13:01。06:13:02。06:14。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）每一天。半年。每天——在 06:13 之前醒來。每天——盯著它越過去。每天——確認。確認——沒有回去。確認——時間還在走。確認——我還在這一輪。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）今天——", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她停了一下。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）今天——我讓它自己過去了。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不是——我沒有醒。我醒了。在 06:13 之前。可是——我沒有盯著時鐘。我——翻了一個身。我聽見悠真在隔壁房間翻身。我聽見外面的電車。我——沒有看。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）06:13 自己過去了。沒有我盯著它。它——自己過去了。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）這不是——完全康復。這是——重新學習空白。學習——不靠倒數活著。學習——讓一分鐘自己過去。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "悠真的房間門開了一條縫。他的聲音傳出來。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraYuma, character: "朝倉悠真", dialogue: "姐。充電器你有沒有看到？", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraYuma_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "書桌第二層。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraYuma, character: "朝倉悠真", dialogue: "⋯⋯哦。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraYuma_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他忘了充電。手機沒電。普通的。不是——追蹤。不是——訊號。只是——忘了充電。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）他忘了充電。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她笑了一下。很小。嘴角動了一下。不是——快樂。是——普通的。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "手機螢幕亮了。一通未接來電。未知號碼。她錯過了。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）錯過了一通電話。不知道是誰。不是——緊急的。不是——循環的。只是——一通普通的電話。我錯過了。沒有——第二輪可以重來接。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）沒有上一輪了。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著未接來電的通知。幾秒。然後——劃掉。不回撥。不是——重要的人。只是——一個普通的未知號碼。在一個普通的日子裡。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "窗外。天氣預報的推送。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "明日天氣——晴轉多雲。原先預報——晴。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）天氣預報改了。原先說晴。現在——晴轉多雲。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）上一輪——不是這樣。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她停了一下。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）沒有上一輪了。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把窗戶關上一半。廚房的燈開了。普通的黃色燈光。冰箱嗡了一聲。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）普通時間。就是——這個。牛奶會過期。電車會延誤。悠真會忘記充電。我會錯過電話。天氣預報會改變。沒有——預先知道。沒有——可以重來。只有——這一次。只有——現在。", background: Background.Chapter_28_Ch28_Act7_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在廚房裡站了一會兒。水龍頭滴了一滴水。她擰緊了。", background: Background.Chapter_28_Ch28_Act7_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "普通的。全部都是普通的。", background: Background.Chapter_28_Ch28_Act7_S1 },
];
